#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t rows = 3, cols = 4;
    int **m = malloc(rows * sizeof(int *));
    if (!m) return 1;
    for (size_t i = 0; i < rows; i++) {
        m[i] = malloc(cols * sizeof(int));
        if (!m[i]) return 1;
        for (size_t j = 0; j < cols; j++) m[i][j] = (int)(i * cols + j);
    }

    for (size_t i = 0; i < rows; i++) {
        for (size_t j = 0; j < cols; j++) printf("%2d ", m[i][j]);
        printf("\n");
    }

    for (size_t i = 0; i < rows; i++) free(m[i]);   /* 逐行释放 */
    free(m);
    m = NULL;
    return 0;
}
